var t=class{constructor(e){this.guild=e}roleMap=new Map;initialized=!1;async initialize(){if(!this.initialized)try{(await this.guild.roles.fetch())?.forEach(r=>{this.roleMap.set(r.name,r)}),this.initialized=!0}catch(e){console.error("Failed to fetch roles:",e)}}getRoleId(e){let r=this.roleMap.get(e);return r?r.id:null}getRole(e){return this.roleMap.get(e)||null}hasRole(e){return this.roleMap.has(e)}getAllRoles(){return Array.from(this.roleMap.values())}};export{t as default};
